I'm currently using this method, which isn't perfect, but simulates pretty accurately how I want/expect the text to behave to "Fit Content Width".

	func _resize_text_edit_to_width() -> void:
		var font: Font = get_theme_default_font()

		var lines: PackedStringArray = []
		if text_edit.text.is_empty():
			lines = text_edit.placeholder_text.split("\n")
		else:
			for line_idx: int in text_edit.get_line_count():
				lines.push_back(text_edit.get_line(line_idx))

		var max_width: int = 0
		for line: String in lines:
			var str_size: int = font.get_string_size(line).x
			if str_size > max_width:
				max_width = str_size

		text_edit.custom_minimum_size.x = max_width + _font_size_margin

